  const T = (title, head, rows, esCols = [1]) => `<div class="tbl-wrap"><table class="tbl"><caption>${esc(title)}</caption><thead><tr>${head.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, k) => `<td class="${esCols.includes(k) ? 'es' : ''}">${esc(c)}${esCols.includes(k) && c && !/^[-–]/.test(c) ? ' ' + UI.spk(c.split(' / ')[0].replace(/[()…]/g, '')) : ''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
