    sentences: [['En el fondo del mar vivía una sirena joven que soñaba con conocer el mundo de los humanos.', 'At the bottom of the sea lived a young mermaid who dreamed of knowing the human world.'], ['Su abuela le había contado que, cuando cumpliera quince años, se le permitiría subir a la superficie.', 'Her grandmother had told her that, when she turned fifteen, she would be allowed to rise to the surface.'], ['El día de su cumpleaños, vio un barco en medio de una tormenta y salvó a un príncipe que se estaba ahogando.', 'On her birthday, she saw a ship in the middle of a storm and saved a prince who was drowning.'], ['Lo dejó en la playa sin que él supiera quién lo había rescatado.', 'She left him on the beach without him knowing who had rescued him.'], ['Desesperada por volver a verlo, visitó a la bruja del mar, quien le ofreció un trato terrible.', 'Desperate to see him again, she visited the sea witch, who offered her a terrible deal.'], ['«Te daré piernas a cambio de tu voz, a condición de que el príncipe se case contigo», le dijo.', '“I will give you legs in exchange for your voice, on condition that the prince marries you,” she told her.'], ['«Si se casa con otra, te convertirás en espuma del mar.»', '“If he marries another, you will turn into sea foam.”'], ['La sirenita aceptó, aunque cada paso que daba le dolía como si pisara cuchillos.', 'The little mermaid accepted, although every step she took hurt as if she were stepping on knives.'], ['El príncipe la trataba con cariño, pero creía que había sido otra joven quien lo había salvado.', 'The prince treated her kindly, but he believed it had been another young woman who had saved him.'], ['Finalmente anunció que se casaría con aquella joven.', 'Finally he announced that he would marry that young woman.'], ['Sus hermanas le explicaron que, si mataba al príncipe, podría volver al mar, pero ella se negó.', 'Her sisters explained that, if she killed the prince, she could return to the sea, but she refused.'], ['Al amanecer se lanzó al agua, y en lugar de convertirse en espuma, fue llevada al cielo por los espíritus del aire.', 'At dawn she threw herself into the water, and instead of turning into foam, she was carried up to the sky by the spirits of the air.']],
    phrases: { 'en el fondo del mar': { en: 'at the bottom of the sea', pos: 'expression' }, 'soñaba con': { en: 'dreamed of', ctx: 'soñar con + infinitive/noun.', pos: 'verb + preposition' }, 'le había contado que': { en: 'had told her that', ctx: 'Pluperfect in reported speech.', pos: 'structure' }, 'cuando cumpliera quince años': { en: 'when she turned fifteen', ctx: 'Future-in-the-past → cuando + imperfect subjunctive.', pos: 'structure' }, 'se le permitiría': { en: 'she would be allowed', ctx: 'Impersonal se + conditional (reported future).', pos: 'structure' }, 'se estaba ahogando': { en: 'was drowning', pos: 'verb' }, 'sin que él supiera': { en: 'without him knowing', ctx: 'sin que + imperfect subjunctive.', pos: 'structure' }, 'volver a verlo': { en: 'to see him again', ctx: 'volver a + infinitive = to do again.', pos: 'structure' }, 'a cambio de': { en: 'in exchange for', pos: 'expression' }, 'a condición de que se case': { en: 'on condition that he marries', ctx: 'Always + subjunctive.', pos: 'structure' }, 'como si pisara cuchillos': { en: 'as if she were stepping on knives', ctx: 'como si + imperfect subjunctive.', pos: 'structure' }, 'había sido otra joven quien': { en: 'it had been another young woman who', pos: 'cleft sentence' }, 'se negó': { en: 'refused', pos: 'verb' }, 'en lugar de': { en: 'instead of', pos: 'expression' }, 'fue llevada': { en: 'was carried', ctx: 'Ser passive (agrees: llevada, f).', pos: 'passive' } },
    gloss: { 'sirena': { en: 'mermaid', pos: 'noun' }, 'joven': { en: 'young; young person', pos: 'adjective/noun' }, 'mundo': { en: 'world', pos: 'noun' }, 'humanos': { en: 'humans', pos: 'noun' }, 'abuela': { en: 'grandmother', pos: 'noun' }, 'superficie': { en: 'surface', pos: 'noun' }, 'cumpleaños': { en: 'birthday', pos: 'noun' }, 'barco': { en: 'ship', pos: 'noun' }, 'tormenta': { en: 'storm', pos: 'noun' }, 'salvó': { en: 'saved', pos: 'verb' }, 'príncipe': { en: 'prince', pos: 'noun' }, 'playa': { en: 'beach', pos: 'noun' }, 'rescatado': { en: 'rescued', pos: 'participle' }, 'desesperada': { en: 'desperate', pos: 'adjective' }, 'bruja': { en: 'witch', pos: 'noun' }, 'trato': { en: 'deal', pos: 'noun' }, 'terrible': { en: 'terrible', pos: 'adjective' }, 'piernas': { en: 'legs', pos: 'noun' }, 'voz': { en: 'voice', pos: 'noun' }, 'espuma': { en: 'foam', pos: 'noun' }, 'aceptó': { en: 'accepted', pos: 'verb' }, 'paso': { en: 'step', pos: 'noun' }, 'dolía': { en: 'hurt', pos: 'verb', gram: 'doler (o→ue), imperfecto' }, 'cuchillos': { en: 'knives', pos: 'noun' }, 'cariño': { en: 'affection', pos: 'noun' }, 'anunció': { en: 'announced', pos: 'verb' }, 'hermanas': { en: 'sisters', pos: 'noun' }, 'mataba': { en: '(if she) killed', pos: 'verb' }, 'amanecer': { en: 'dawn', pos: 'noun' }, 'lanzó': { en: 'threw (herself)', pos: 'verb' }, 'cielo': { en: 'sky', pos: 'noun' }, 'espíritus': { en: 'spirits', pos: 'noun' }, 'aire': { en: 'air', pos: 'noun' } },
