  MA.RADIO.push({ id: 'r7', city: 'sevilla', title: 'Tertulia en Radio Guadalquivir', en: 'Talk-show debate on Radio Guadalquivir', level: 'B2', type: 'Radio tertulia', unlock: null,
    desc: 'Lola moderates a tertulia (panel debate): should Seville move the April Fair dates to avoid extreme heat?',
    lines: [['L', 'Muy buenas tardes. En la tertulia de hoy hablamos de un tema que divide a Sevilla: ¿debería adelantarse la Feria por el calor?', 'Good afternoon. In today’s tertulia we discuss a topic that divides Seville: should the Fair be moved earlier because of the heat?'], ['L', 'Me acompañan Manuel, historiador, y Carmen, médica de urgencias. Manuel, usted primero.', 'With me are Manuel, a historian, and Carmen, an emergency doctor. Manuel, you first.'], ['M', 'Gracias, Lola. En primer lugar, la Feria tiene una tradición de casi doscientos años. No creo que debamos cambiarla por unos grados más.', 'Thank you, Lola. Firstly, the Fair has a tradition of almost two hundred years. I don’t think we should change it for a few degrees more.'], ['C', 'Perdone que le interrumpa, pero no son «unos grados». El año pasado se atendieron más de trescientos golpes de calor.', 'Sorry to interrupt, but it isn’t “a few degrees”. Last year more than three hundred cases of heatstroke were treated.'], ['M', 'Le doy la razón en que es un problema. No obstante, se podrían instalar más zonas de sombra sin que haya que cambiar las fechas.', 'I grant you it is a problem. Nevertheless, more shaded areas could be installed without having to change the dates.'], ['C', 'Mire, si hubiéramos tomado medidas hace diez años, hoy no estaríamos discutiendo esto.', 'Look, if we had taken measures ten years ago, we wouldn’t be arguing about this today.'], ['L', 'Carmen, ¿qué propondría usted exactamente?', 'Carmen, what exactly would you propose?'], ['C', 'Propongo que la Feria se celebre dos semanas antes, siempre que el Ayuntamiento lo apruebe con los vecinos.', 'I propose that the Fair be held two weeks earlier, provided that the City Council approves it with the residents.'], ['M', 'Bueno, si se consulta a los sevillanos, no me opongo. Que decida la ciudad.', 'Well, if Sevillians are consulted, I don’t object. Let the city decide.'], ['L', 'Pues parece que, por una vez, llegamos a un acuerdo. Gracias a los dos, y hasta la semana que viene.', 'Well, it seems that, for once, we reach an agreement. Thanks to both of you, and until next week.']],
    voices: { L: 'airy', M: 'rounded', C: 'glassy' }, names: { L: 'Lola', M: 'Manuel', C: 'Carmen' },
    quiz: [{ q: 'What is Carmen’s profession?', o: ['Historian', 'Emergency doctor', 'Journalist'], a: 1 }, { q: 'What does Manuel propose first?', o: ['Moving the dates', 'More shaded areas', 'Cancelling the Fair'], a: 1 }, { q: '«si hubiéramos tomado medidas…, no estaríamos discutiendo» is…', o: ['a real condition', 'a mixed hypothetical (past condition, present result)', 'reported speech'], a: 1 }, { q: 'How does the debate end?', o: ['With an agreement to consult the city', 'With no agreement', 'With the Fair cancelled'], a: 0 }],
    dictation: ['Perdone que le interrumpa.', 'Propongo que la Feria se celebre dos semanas antes.'] });

